const { messages, status, sendMessage, stop, reload } = useChat();
const [text, setText] = useState("");

<ChatComposer
  product="Helper"
  messages={messages.map((m) => ({ id: m.id, role: m.role, text: m.content }))}
  status={status}
  value={text}
  onChange={setText}
  onSend={({ text, attachments }) => sendMessage({ text, files: attachments.map((a) => a.file) })}
  onStop={stop}
  onRetry={reload}
  accept={["pdf", "png"]}
  maxSizeMB={10}
  onReject={(file, err) => toast(err.message)}
  height={560}
/>
